static int 
dtb_message_ed_dialog_create(
    DtbMessageEdDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    Arg	args[8];	/* need 3 args (add 5 to be safe) */
    int	n = 0;
    String	title_str = NULL;
    static DtbObjectHelpDataRec	help_data = {
        "",
        "AppBuilder",
        "ABMessagesEditor",
    };
    char *tmp_txt;
    
    if (instance->dialog == NULL) {
        title_str = XtNewString(CATGETS(Dtb_project_catd, 34, 1, "Message Editor"));
        n = 0;
        XtSetArg(args[n], XmNallowShellResize, True);  ++n;
        XtSetArg(args[n], XmNtitle, title_str);  ++n;
        XtSetArg(args[n], XmNbackground, dtb_cvt_string_to_pixel(parent, "white"));  ++n;
        instance->dialog =
            XmCreateDialogShell(parent,
                "dtb_message_ed_dialog", args, n);
        XtFree(title_str);
        title_str = NULL;
    }
    if (instance->dialog == NULL)
        return -1;

    if (instance->dialog_shellform == NULL) {
        instance->dialog_shellform =
            XtVaCreateWidget("dtb_message_ed_dialog_shellform",
                xmFormWidgetClass,
                instance->dialog,
                XmNdefaultPosition, False,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->dialog, "white"),
                NULL);
        /*
         * Add help callback
         */
        tmp_txt = CATGETS(Dtb_project_catd, 34, 41, "The Message Editor allows application message dialogs to be defined and configured.");
        help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
        strcpy(help_data.help_text,tmp_txt);
        
        XtAddCallback(instance->dialog_shellform,
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    if (instance->dialog_shellform == NULL)
        return -1;

    if (instance->dialog_panedwin == NULL) {
        instance->dialog_panedwin =
            XtVaCreateWidget("dialog_panedwin",
                xmPanedWindowWidgetClass,
                instance->dialog_shellform,
                XmNbottomOffset, 0,
                XmNbottomPosition, 100,
                XmNbottomAttachment, XmATTACH_POSITION,
                XmNrightOffset, 0,
                XmNrightPosition, 100,
                XmNrightAttachment, XmATTACH_POSITION,
                XmNleftOffset, 0,
                XmNleftPosition, 0,
                XmNleftAttachment, XmATTACH_POSITION,
                XmNtopOffset, 0,
                XmNtopPosition, 0,
                XmNtopAttachment, XmATTACH_POSITION,
                XmNsashWidth, 1,
                XmNsashHeight, 1,
                XmNspacing, 0,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->dialog_shellform, "white"),
                NULL);
    }
    if (instance->dialog_panedwin == NULL)
        return -1;

    if (instance->dialog_form == NULL) {
        instance->dialog_form =
            XtVaCreateWidget("dialog_form",
                xmFormWidgetClass,
                instance->dialog_panedwin,
                XmNallowResize, True,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_ANY,
                XmNbackground, dtb_cvt_string_to_pixel(instance->dialog_panedwin, "white"),
                NULL);
    }
    if (instance->dialog_form == NULL)
        return -1;

    return 0;
}



